"use client";

import { useState, useEffect } from "react";
import { useSubmit } from "@/lib/api";
import { Card, Skeleton, FormModal } from "@/components/finance";
import { TRANSACTION_CATEGORIES, ACCOUNT_TYPES, GOAL_TYPES, INSURANCE_TYPES, SALARY_TYPES } from "@/components/finance/constants";
import { AccountForm, TransactionForm, HoldingForm, DebtForm, GoalForm, InsuranceForm, SalaryForm } from "@/components/finance/forms";
import { useFinanceData } from "@/lib/api";

const SettingsPage = () => {
  const [activeTab, setActiveTab] = useState("accounts");
  const [accounts, setAccounts] = useState([]);
  const [goals, setGoals] = useState([]);
  const [insurances, setInsurances] = useState([]);
  const [salaries, setSalaries] = useState([]);

  const { data: accountData, isLoading: accountLoading, error: accountError } = useFinanceData("/accounts");
  const { data: goalData, isLoading: goalLoading, error: goalError } = useFinanceData("/goals");
  const { data: insuranceData, isLoading: insuranceLoading, error: insuranceError } = useFinanceData("/insurance");
  const { data: salaryData, isLoading: salaryLoading, error: salaryError } = useFinanceData("/salary");

  useEffect(() => {
    if (accountData) setAccounts(accountData);
    if (goalData) setGoals(goalData);
    if (insuranceData) setInsurances(insuranceData);
    if (salaryData) setSalaries(salaryData);
  }, [accountData, goalData, insuranceData, salaryData]);

  const handleTabChange = (tab) => {
    setActiveTab(tab);
  };

  const handleFormSubmit = (path, data) => {
    useSubmit(path, "POST")(data);
  };

  return (
    <div className="flex flex-col">
      <div className="flex justify-center space-x-4">
        <button
          className={`px-4 py-2 rounded bg-blue-500 text-white ${activeTab === "accounts" ? "bg-blue-700" : ""}`}
          onClick={() => handleTabChange("accounts")}
        >
          Accounts
        </button>
        <button
          className={`px-4 py-2 rounded bg-blue-500 text-white ${activeTab === "goals" ? "bg-blue-700" : ""}`}
          onClick={() => handleTabChange("goals")}
        >
          Goals
        </button>
        <button
          className={`px-4 py-2 rounded bg-blue-500 text-white ${activeTab === "insurances" ? "bg-blue-700" : ""}`}
          onClick={() => handleTabChange("insurances")}
        >
          Insurances
        </button>
        <button
          className={`px-4 py-2 rounded bg-blue-500 text-white ${activeTab === "salaries" ? "bg-blue-700" : ""}`}
          onClick={() => handleTabChange("salaries")}
        >
          Salaries
        </button>
      </div>
      <div className="mt-4">
        {activeTab === "accounts" && (
          <div>
            <h2 className="text-lg font-bold">Accounts</h2>
            {accountLoading ? (
              <Skeleton />
            ) : accountError ? (
              <div>Error: {accountError.message}</div>
            ) : (
              <div>
                {accounts.map((account) => (
                  <Card key={account.id} title={account.name} description={account.description} />
                ))}
              </div>
            )}
            <FormModal title="Add Account" onSubmit={(data) => handleFormSubmit("/accounts", data)}>
              <AccountForm />
            </FormModal>
          </div>
        )}
        {activeTab === "goals" && (
          <div>
            <h2 className="text-lg font-bold">Goals</h2>
            {goalLoading ? (
              <Skeleton />
            ) : goalError ? (
              <div>Error: {goalError.message}</div>
            ) : (
              <div>
                {goals.map((goal) => (
                  <Card key={goal.id} title={goal.name} description={goal.description} />
                ))}
              </div>
            )}
            <FormModal title="Add Goal" onSubmit={(data) => handleFormSubmit("/goals", data)}>
              <GoalForm />
            </FormModal>
          </div>
        )}
        {activeTab === "insurances" && (
          <div>
            <h2 className="text-lg font-bold">Insurances</h2>
            {insuranceLoading ? (
              <Skeleton />
            ) : insuranceError ? (
              <div>Error: {insuranceError.message}</div>
            ) : (
              <div>
                {insurances.map((insurance) => (
                  <Card key={insurance.id} title={insurance.name} description={insurance.description} />
                ))}
              </div>
            )}
            <FormModal title="Add Insurance" onSubmit={(data) => handleFormSubmit("/insurance", data)}>
              <InsuranceForm />
            </FormModal>
          </div>
        )}
        {activeTab === "salaries" && (
          <div>
            <h2 className="text-lg font-bold">Salaries</h2>
            {salaryLoading ? (
              <Skeleton />
            ) : salaryError ? (
              <div>Error: {salaryError.message}</div>
            ) : (
              <div>
                {salaries.map((salary) => (
                  <Card key={salary.id} title={salary.name} description={salary.description} />
                ))}
              </div>
            )}
            <FormModal title="Add Salary" onSubmit={(data) => handleFormSubmit("/salary", data)}>
              <SalaryForm />
            </FormModal>
          </div>
        )}
      </div>
    </div>
  );
};

export default SettingsPage;
